function read(form){const out={};for(const el of form.elements)if(el.name)out[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;return out;}
function icon(name,fill=false){return `<svg class="icon${fill?' fill':''}" aria-hidden="true"><use href="#i-${esc(name)}"></use></svg>`;}
const metricIcons={'Home Wi-Fi':'wifi','Decoded packets':'packets','MQTT':'mqtt','Free heap':'memory','Uptime':'clock'};
function card(title,value,unit=''){return `<section class="card"><div class="label">${metricIcons[title]?icon(metricIcons[title]):''}${esc(title)}</div><div class="metric">${esc(value)} <small>${esc(unit)}</small></div></section>`;}
function internetCard(internet={}){
    const enabled=config.probe_enabled!==false,status=internet.status||'unknown / disabled';
    const reachable=enabled&&status==='probe reachable',failed=enabled&&status==='probe did not reply';
    const value=!enabled?'Not tested':reachable?'Online':failed?'Offline':'Checking';
    const tone=reachable?'online':failed?'offline':'unknown';
    const latency=reachable&&Number.isFinite(internet.latency_ms)?` · ${Math.max(0,Math.round(internet.latency_ms))} ms`:'';
    const fallback=internet.offline_mode?'Local fallback active':`Every 30s${latency}`;
    return `<section class="card internet-card" title="ICMP probe ${esc(config.probe_ip||'not configured')}: ${esc(status)}"><div class="label">${icon('internet')}Internet</div><div class="metric status-metric"><span class="status-light ${tone}" aria-hidden="true"></span><span>${value}</span></div><div class="metric-detail"><code>${esc(config.probe_ip||'Not configured')}</code><span>${fallback}</span></div></section>`;
}
let inverterSlot=1;
const decoderProfiles={inteless_sp_legacy:{label:'Inteless / Sunsynk – Legacy single-phase (292 bytes)',layout:292},inteless_sp_newer:{label:'Inteless / Sunsynk – Newer single-phase (302 bytes)',layout:302},inteless_sp_captured_306:{label:'Inteless / Sunsynk – Captured variant (306 bytes)',layout:306}};
