function dongleMaps(){const maps=config.dongles||Array.from({length:8},(_,i)=>({ip:'',name:'INVERTER'+(i+1),layout:config.layout||292,cloud_forward:true}));return maps.map(m=>({...m,profile:m.profile||profileFromLayout(m.layout)}));}
function ensureInverterSlot(){const maps=dongleMaps();if(!maps[inverterSlot-1]?.ip){const first=maps.findIndex(m=>m.ip);if(first>=0)inverterSlot=first+1;}}
function sourceRecords(r){
    const observed=r.dongles||[],maps=dongleMaps();
    const records=maps.filter(m=>m.ip).map(m=>({...observed.find(d=>d.dongle_ip===m.ip),dongle_ip:m.ip,name:m.name,mapped:true}));
    for(const d of observed)if(!maps.some(m=>m.ip===d.dongle_ip))records.push({...d,name:'Unmapped '+d.dongle_ip,mapped:false});
    return records;
}
function inverterSelector(){const maps=dongleMaps(),active=maps.map((m,i)=>({...m,slot:i+1})).filter(m=>m.ip);if(active.length&&!active.some(m=>m.slot===inverterSlot))inverterSlot=active[0].slot;return `<label class="inverter-selector">Inverter<select id="inverter-select" ${active.length?'':'disabled'}>${active.length?active.map(m=>`<option value="${m.slot}" ${inverterSlot===m.slot?'selected':''}>${esc(m.name)} - ${esc(m.ip)}</option>`).join(''):'<option>No inverters configured</option>'}</select></label>`;}
