    const remove=$('#remove-dongle');if(remove)remove.onclick=async()=>{try{if(!confirm(`Remove ${m.name}?`))return;maps[slot]={ip:'',name:`INVERTER${slot+1}`,profile:'inteless_sp_legacy',cloud_forward:true};await saveDongles(maps,'Dongle removed.');close();await refresh();}catch(error){notice(error.message,true);}};
    const reboot=$('#dongle-reboot');if(reboot)reboot.onclick=async()=>{try{if(!confirm(`Reboot ${m.name}?`))return;await api('dongle-reboot',{ip:m.ip});notice('Reboot requested.');}catch(error){notice(error.message,true);}};
    const guiButton=$('#dongle-gui-toggle');if(guiButton)guiButton.onclick=async()=>{try{g.dongle_gui=await api('dongle-gui',{enabled:!guiHere,ip:m.ip});openDongleDialog(slot,r,g);notice(guiHere?'Dongle web GUI disabled.':'Dongle web GUI enabled for 15 minutes.');}catch(error){notice(error.message,true);}};
    if(!adding){const target=$('#dongle-packet-info');api('dongle-info',{ip:m.ip}).then(info=>{if(target)target.innerHTML=`<dl class="info-list"><div><dt>Dongle serial</dt><dd><code>${esc(info.serial||'Not observed')}</code></dd></div><div><dt>Register Key</dt><dd><code>${esc(info.register_key||'Not observed')}</code></dd></div><div><dt>Captured</dt><dd>${esc(Number.isFinite(info.observed_seconds_ago)?`${info.observed_seconds_ago} seconds ago`:'Unknown')}</dd></div></dl><p class="section-note">Read from the dongle's cloud login packet. The Register Key is sensitive.</p>`;}).catch(()=>{if(target)target.innerHTML='<p class="empty-state">No identity packet has been observed for this dongle yet.</p>';});}
    if(!dialog.hasAttribute('open')){if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
