function livePackets(){
    $('#content').innerHTML=heading('Live packet capture','Download live traffic or inspect a saved PCAP locally in this browser.')+`<section class="card"><h3>Live PCAP download</h3><p>Captures may contain identifiers and private traffic. Packets are sent directly to this browser and are never retained in RAM or flash.</p><div class="row"><a class="button" id="capture-stream" href="/api/capture-stream" download="solarproxxie-live.pcap">Start live PCAP download</a><button id="capture-stream-stop" class="secondary">Finish download</button><button id="capture-refresh" class="secondary">Refresh status</button></div><p id="capture-state" role="status">Loading...</p><p>Keep this browser connected while downloading. Finish the download before opening it below or in Wireshark.</p></section><section class="card" id="pcap-reader"><h3>Open and inspect PCAP</h3><p>Select a classic PCAP file. It is read locally by JavaScript and is not uploaded to SolarProxxie.</p><div class="row pcap-file-row"><input id="pcap-file" type="file" accept=".pcap,application/vnd.tcpdump.pcap,application/octet-stream"><button id="pcap-load" type="button" class="compact-action">Read PCAP</button></div><p id="pcap-summary" class="section-note">No PCAP loaded.</p><div id="pcap-list" class="table-wrap" hidden></div><div id="pcap-detail" class="packet-detail"></div></section>`;
    bind('#capture-stream-stop',async()=>{await api('action',{command:'stop-stream'});await refreshPackets();});
    bind('#capture-refresh',refreshPackets);
    bind('#pcap-load',async()=>{await loadPcapFile();$('#pcap-list').hidden=false;});
    $('#pcap-file').onchange=async()=>{try{await loadPcapFile();$('#pcap-list').hidden=false;}catch(e){notice(e.message,true);}};
    refreshPackets().catch(e=>notice(e.message,true));
}
function renderCloudUpdate(update){const target=$('#cloud-update-status');if(!target)return;const latest=update.latest||'Not checked',size=update.bytes?` · ${(update.bytes/1024).toFixed(0)} KiB`:'';target.innerHTML=`<dl class="info-list"><div><dt>Installed</dt><dd>v${esc(update.current||firmwareVersion)}</dd></div><div><dt>Latest release</dt><dd>${latest==='Not checked'?latest:`v${esc(latest)}${size}`}</dd></div><div><dt>Status</dt><dd>${esc(update.status||'Not checked')}</dd></div></dl>`;const check=$('#check-cloud-update'),install=$('#install-cloud-update');if(check){check.disabled=!!update.busy;check.textContent=update.busy?'Update in progress…':'Check GitHub';}if(install){install.hidden=!update.available;install.disabled=!!update.busy;install.dataset.version=update.latest||'';}if(update.busy&&page==='Firmware')setTimeout(()=>api('update').then(renderCloudUpdate).catch(e=>notice(e.message,true)),1500);}
function firmware(){$('#content').innerHTML=heading('Firmware update','Install a published GitHub release or upload a SolarProxxie application image.')+`<div class="firmware-grid"><section class="card compact" id="cloud-update"><h3>Update from GitHub</h3><p>Checks the latest published release at <code>martinville/SolarProxxie</code>. Only its <code>SolarProxxie.bin</code> release asset is accepted. The download uses certificate-verified HTTPS and the embedded project name and version are checked before activation.</p><div id="cloud-update-status"><p>Loading update status…</p></div><div class="row"><button id="check-cloud-update">Check GitHub</button><button id="install-cloud-update" class="danger" hidden>Install update & restart</button></div><p class="section-note">The release image is transported over verified HTTPS but is not cryptographically signed by this project unless Secure Boot and signed-image validation are provisioned separately.</p></section><section class="card compact"><h3>Upload application image</h3><p>Use <code>build/SolarProxxie.bin</code>. The inactive OTA slot is written and validated before restart. Configuration is preserved. Keep power connected during the update.</p><label>Application firmware<input id="image" type="file" accept=".bin"></label><button id="upload">Upload & restart</button><p id="upload-status"></p><progress id="progress" value="0" max="100"></progress></section></div>`;bind('#check-cloud-update',async()=>renderCloudUpdate(await api('update',{action:'check'})));bind('#install-cloud-update',async()=>{const button=$('#install-cloud-update'),version=button.dataset.version;if(!version||!confirm(`Download and install SolarProxxie v${version} from GitHub? Keep power connected.`))return;renderCloudUpdate(await api('update',{action:'install',version}));});api('update').then(renderCloudUpdate).catch(e=>notice(e.message,true));bind('#upload',()=>{const file=$('#image').files[0];if(!file||file.size>1966080)throw Error('Choose an ESP32 application .bin smaller than the 1.875 MiB OTA slot.');if(!confirm('Install this firmware and restart SolarProxxie?'))return;const x=new XMLHttpRequest();x.open('POST','/api/ota');x.setRequestHeader('X-CSRF-Token',token);x.setRequestHeader('Content-Type','application/octet-stream');x.upload.onprogress=e=>{if(e.lengthComputable){$('#progress').value=e.loaded/e.total*100;$('#upload-status').textContent=Math.round(e.loaded/e.total*100)+'% uploaded';}};x.onload=()=>{notice(x.status===200?'Image validated. Restarting…':x.responseText,x.status!==200);$('#upload').disabled=false;};x.onerror=()=>{notice('Upload connection interrupted.',true);$('#upload').disabled=false;};$('#upload').disabled=true;x.send(file);});}
async function about(){
    const status=await api('status'),system=status.system||{};
    const build={version:system.version||'Unknown',git_commit:system.git_commit||'Unavailable',build_date:system.build_date||'Unknown',build_time:system.build_time||'Unknown',idf:system.idf||'Unknown'};
    const footerVersion=$('#firmware-version');if(footerVersion)footerVersion.textContent='v'+build.version;
    $('#content').innerHTML=heading('SolarProxxie','Inverter Gateway • Monitor • MQTT Bridge')+`<section class="card"><h3>How it works</h3><p>The dongle connects to the SolarProxxie access point, which forwards its traffic through your home Wi-Fi. SolarProxxie passively reads supported telemetry and publishes it to MQTT and Home Assistant. It does not generate inverter commands. The optional dongle GUI access lets you interact with the dongle's own controls.</p></section><section class="card"><h3>Copyright, license & credits</h3><p><strong>Copyright © 2026 Martin Viljoen.</strong></p><p>SolarProxxie is free software distributed under the <strong>GNU General Public License v3.0 or later</strong> (<code>GPL-3.0-or-later</code>). You may use, modify and redistribute it under those license terms. It is provided without warranty.</p><h4>Sources and third-party software</h4><dl class="credits-list"><div><dt>SolarProxxie firmware, web UI and tools</dt><dd>Martin Viljoen · GPL-3.0-or-later</dd></div><div><dt>Bruce Merry — sunsniff</dt><dd>Register names, offsets and packet-layout reference · GPL-3.0</dd></div><div><dt>Johann Kellerman — kellerza/sunsynk</dt><dd>Candidate field names and scaling cross-check · Apache-2.0</dd></div><div><dt>Espressif ESP-IDF 5.4.2</dt><dd>Firmware SDK · Apache-2.0, with bundled components retaining their own licenses</dd></div><div><dt>FreeRTOS Kernel</dt><dd>Task scheduler used through ESP-IDF · MIT</dd></div><div><dt>lwIP</dt><dd>TCP/IP, routing and NAPT stack used through ESP-IDF · BSD-3-Clause</dd></div><div><dt>Mbed TLS</dt><dd>Cryptographic primitives used through ESP-IDF · Apache-2.0 OR GPL-2.0-or-later</dd></div><div><dt>cJSON</dt><dd>JSON parser and generator used through ESP-IDF · MIT</dd></div><div><dt>Espressif ESP-MQTT</dt><dd>MQTT client used through ESP-IDF · Apache-2.0</dd></div><div><dt>Linkedom 0.18.12</dt><dd>Development-only DOM testing · ISC; not embedded in firmware</dd></div><div><dt>Linkedom dependency tree</dt><dd>boolbase, css-select, css-what, cssom, dom-serializer, domelementtype, domhandler, domutils, entities, html-escaper, htmlparser2, nth-check and uhyphen · ISC, MIT or BSD-2-Clause; development-only</dd></div><div><dt>Protocol evidence</dt><dd>Owner-supplied packet captures and Sunsynk/Deye Modbus reference material; product names and trademarks remain the property of their respective owners</dd></div></dl><p class="section-note">Full license texts and attribution details are provided in <code>LICENSE</code>, <code>NOTICE.md</code>, the npm lockfile and the ESP-IDF SDK copyright files included with the source/build environment.</p></section><section class="card"><h3>Security</h3><p>Use HTTP management and unencrypted MQTT on trusted local networks. Temporary dongle GUI access exposes the dongle's own login on your home network. Flash encryption is not enabled in the default build and requires separate device provisioning.</p></section><section class="card"><h3>Physical recovery</h3><p>Press BOOT during the first five seconds to enter Setup Mode. Hold BOOT for ten seconds while running to erase configuration. Do not hold BOOT while applying power: it may enter the ESP32 ROM loader.</p></section>`;
    $('#content .subhead').insertAdjacentHTML('afterend',`<section class="card" id="build-info"><h3>Firmware & build</h3>${infoTree(build)}</section>`);
}
function wizard(){const titles=['Welcome','Home Wi-Fi','IP configuration','Gateway AP','Administrator','Review'];$('#nav').innerHTML='';$('#content').innerHTML=heading('Welcome to SolarProxxie','Set up your local inverter gateway. This temporary AP closes after 15 minutes.')+`<div class="steps">${titles.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><section class="card"><h3>${step+1} / 6 · ${titles[step]}</h3><form id="wizard"><div id="fields"></div><div class="row"><button id="back" type="button" class="secondary" ${step===0?'disabled':''}>Back</button><button>${step===5?'Save & restart':'Continue →'}</button></div></form></section>`;
    let h='';if(step===0)h='<p>Connect this ESP32 to your home network, then connect the Inteless dongle to the SolarProxxie AP. Have your Wi-Fi and MQTT details ready.</p><p>The gateway only observes telemetry. Initial setup does not send inverter commands.</p>';
    if(step===1)h=`${input('sta_ssid','Home Wi-Fi SSID',draft.sta_ssid)}${input('sta_password','Home Wi-Fi password',draft.sta_password,'password')}<button id="scan" type="button" class="secondary">Scan for Wi-Fi networks</button><div id="networks"></div>`;
    if(step===2)h=`<p class="warning">Static IP is highly recommended.</p>${check('dhcp','Use DHCP (automatic IP)',draft.dhcp)}<p>Fill the following fields when DHCP is disabled.</p>${input('ip','Static IP',draft.ip)}${input('mask','Subnet mask',draft.mask)}${input('gateway','Gateway',draft.gateway)}${input('dns1','DNS 1',draft.dns1)}${input('dns2','DNS 2 (optional)',draft.dns2)}`;
    if(step===3)h=`<p>The Inteless dongle will connect to this protected AP. Use a different subnet from your home network.</p>${input('ap_ssid','SolarProxxie AP SSID',draft.ap_ssid)}${input('ap_password','AP password (8–63 characters)',draft.ap_password,'password')}${input('ap_ip','AP gateway IP (host 1)',draft.ap_ip)}${input('ap_mask','AP subnet mask (/16 through /26)',draft.ap_mask)}`;
    if(step===4)h=`${input('admin','Administrator username',draft.admin)}${input('admin_password','Administrator password (12–128 characters)',draft.admin_password,'password')}<p>These settings can also be updated later under Settings.</p>`;
    if(step===5)h=`<p>Home Wi-Fi: <strong>${esc(draft.sta_ssid)}</strong><br>STA IP: ${draft.dhcp?'DHCP':esc(draft.ip)}<br>Dongle AP: <strong>${esc(draft.ap_ssid)}</strong><br>AP gateway: ${esc(draft.ap_ip)}<br>Administrator: ${esc(draft.admin)}</p><p>After setup, add and manage dongles from <strong>Dongles</strong>.</p><button id="wifi-test" type="button" class="secondary">Test Wi-Fi</button><p id="wifi-result">Test before saving. Your browser may briefly lose the AP connection when the radio changes channel.</p>${check('save_without_wifi','Save without a successful Wi-Fi test (explicit override)',false)}`;
    $('#fields').innerHTML=h;bind('#back',()=>{Object.assign(draft,read($('#wizard')));step--;wizard();});
    bind('#scan',async()=>{const a=await api('scan');const security=['Open','WEP','WPA','WPA2','WPA/WPA2','Enterprise','WPA3','WPA2/WPA3'];$('#networks').innerHTML=a.map((n,i)=>`<button class="scan secondary" type="button" data-network="${i}">${esc(n.ssid)} · ${n.rssi} dBm · ${security[n.security]||'Secured'}</button>`).join('');document.querySelectorAll('[data-network]').forEach(b=>b.onclick=()=>{$('[name=sta_ssid]').value=a[Number(b.dataset.network)].ssid;});});
    bind('#wifi-test',async()=>{await api('wifi-test',draft);$('#wifi-result').textContent='Testing… Wait a few seconds, then check the result.';setTimeout(async()=>{try{const s=await api('status');$('#wifi-result').textContent=s.network.sta_connected?'Wi-Fi connected: '+s.network.sta_ip:'Not connected yet. Check credentials, signal and subnet.';}catch(e){notice('Reconnect to the setup AP to check the test.',true);}},8000);});
    $('#wizard').onsubmit=async e=>{e.preventDefault();Object.assign(draft,read(e.target));try{if(step===1&&!draft.sta_ssid)throw Error('Enter a home Wi-Fi SSID.');if(step===2&&!draft.dhcp&&![draft.ip,draft.mask,draft.gateway,draft.dns1].every(x=>/^\d{1,3}(\.\d{1,3}){3}$/.test(x)))throw Error('Enter valid static IPv4 settings.');if(step===3&&(!draft.ap_ssid||draft.ap_password.length<8))throw Error('Set an AP SSID and password of at least 8 characters.');if(step===4&&(!draft.admin||draft.admin_password.length<12))throw Error('Set an admin username and password of at least 12 characters.');if(step<5){step++;wizard();}else{await api('setup',draft);$('#content').innerHTML=heading('Setup complete.','Your settings have been saved. SolarProxxie is restarting.')+`<section class="card"><p>Reconnect to your home Wi-Fi and open ${draft.dhcp?'the ESP32 address shown by your router':esc('http://'+draft.ip)}. Connect the Inteless dongle to <strong>${esc(draft.ap_ssid)}</strong>, then add it under Dongles.</p></section>`;}}catch(e){notice(e.message,true);}};
}
